// Motor de reglas financieras
const transactions = $('Consultar transacciones').all().map(i => i.json);
const totalIngresos = parseFloat($('Consultar ingresos del mes').first().json.total_ingresos);
const userId = $('Webhook: Nueva transacción').first().json.body.userId;
const recommendations = [];

// Valores por defecto: umbrales y plantillas embebidos del motor original (HU-20).
// Solo se usan de fallback si la consulta "Consultar reglas" falla o no devuelve nada.
// Si el fetch funciona, rigen las reglas de la base de datos (una regla desactivada
// simplemente no se ejecuta, porque no se sirve en GET /api/internal/rules).
const REGLAS_DEFAULT = {
  regla1: {
    parametros: { umbralPorcentaje: 30 },
    plantilla: 'Tu gasto en ${cat} representa el ${porcentaje.toFixed(1)}% de tus ingresos. Considera reducirlo para mantener un balance saludable.'
  },
  regla2: {
    parametros: { ratioMaximo: 0.8 },
    plantilla: 'Tus gastos superan el 80% de tus ingresos este mes. Es recomendable mantener los gastos por debajo del 70% para poder ahorrar.'
  },
  regla3: {
    parametros: { porcentajeAhorro: 10 },
    plantilla: 'No hemos registrado movimientos de ahorro este mes. Te recomendamos destinar al menos el 10% de tus ingresos a una meta de ahorro.'
  },
  regla4: {
    parametros: { minMovimientos: 3, varianzaMaxima: 0.2, stddevDias: 5 },
    plantilla: 'Hemos detectado gastos recurrentes en ${cat} (${entries.length} veces este mes). Podría ser una suscripción que vale la pena revisar.'
  }
};

// Reglas activas servidas por GET /api/internal/rules (con X-API-Key)
let fetchedRules = [];
try {
  const items = $('Consultar reglas').all().map(i => i.json);
  const flat = (items.length === 1 && Array.isArray(items[0])) ? items[0] : items;
  // Filtra items de error (p. ej. salida "continue on error" del nodo HTTP)
  fetchedRules = flat.filter(r => r && r.key);
} catch (e) {
  fetchedRules = [];
}
const useDefaults = fetchedRules.length === 0;
const rulesByKey = {};
if (!useDefaults) {
  fetchedRules.forEach(r => { rulesByKey[r.key] = r; });
}
// Devuelve null si la regla está desactivada o no existe en la BD
const getRule = (key) => {
  if (useDefaults) return REGLAS_DEFAULT[key] || null;
  const rule = rulesByKey[key];
  if (!rule || rule.activa === false) return null;
  return rule;
};
// Los defaults cubren parámetros faltantes en la BD (resiliencia ante edits parciales)
const paramsOf = (key, rule) => ({
  ...(REGLAS_DEFAULT[key] ? REGLAS_DEFAULT[key].parametros : {}),
  ...(rule && rule.parametros ? rule.parametros : {})
});
// Renderiza plantillas con expresiones ${...} copiadas textualmente del motor original
const render = (tpl, vars) => {
  try {
    const names = Object.keys(vars);
    const values = Object.values(vars);
    return Function(...names, 'return `' + tpl + '`;')(...values);
  } catch (e) {
    return String(tpl);
  }
};

// Agrupar gastos por categoría
const gastosPorCategoria = {};
const gastosRecientes = {};
let totalEgresos = 0;

transactions.forEach(t => {
  if (t.tipo === 'egreso') {
    totalEgresos += parseFloat(t.monto);
    const cat = t.category?.nombre || 'Sin categoría';
    gastosPorCategoria[cat] = (gastosPorCategoria[cat] || 0) + parseFloat(t.monto);

    // Track recent spending for subscription detection (store date + amount)
    const key = `${cat}-${t.descripcion || 'sin-desc'}`;
    if (!gastosRecientes[key]) gastosRecientes[key] = [];
    gastosRecientes[key].push({ fecha: new Date(t.fecha), monto: parseFloat(t.monto) });
  }
});

// Regla 1: Gasto en categoría > umbral % del ingreso mensual (default 30%)
const r1 = getRule('regla1');
if (r1 && totalIngresos > 0) {
  const umbral = Number(paramsOf('regla1', r1).umbralPorcentaje ?? 30);
  for (const [cat, total] of Object.entries(gastosPorCategoria)) {
    const porcentaje = (total / totalIngresos) * 100;
    if (porcentaje > umbral) {
      recommendations.push({
        user_id: userId,
        contenido: render(r1.plantilla, { cat, porcentaje }),
        tipo: 'alerta',
        leida: false
      });
    }
  }
}

// Regla 2: Gastos totales > ratio máximo de ingresos (default 0.8)
const r2 = getRule('regla2');
if (r2 && totalIngresos > 0) {
  const ratioMaximo = Number(paramsOf('regla2', r2).ratioMaximo ?? 0.8);
  if ((totalEgresos / totalIngresos) > ratioMaximo) {
    recommendations.push({
      user_id: userId,
      contenido: render(r2.plantilla, {}),
      tipo: 'alerta',
      leida: false
    });
  }
}

// Regla 3: Sin ahorro registrado (default: aconsejar 10% de ahorro)
const r3 = getRule('regla3');
const hayAhorro = transactions.some(t =>
  t.tipo === 'egreso' && t.category?.nombre?.toLowerCase().includes('ahorro')
);
if (r3 && !hayAhorro && totalIngresos > 0) {
  recommendations.push({
    user_id: userId,
    contenido: render(r3.plantilla, {}),
    tipo: 'ahorro',
    leida: false
  });
}

// Regla 4: Gastos recurrentes (posibles suscripciones)
// Checks similar amounts (within varianza máxima, default 20%) AND evenly
// spaced dates (stddev within stddevDias, default 5 días), min movimientos default 3
const r4 = getRule('regla4');
if (r4) {
  const p4 = paramsOf('regla4', r4);
  const minMovimientos = Number(p4.minMovimientos ?? 3);
  const varianzaMaxima = Number(p4.varianzaMaxima ?? 0.2);
  const stddevDias = Number(p4.stddevDias ?? 5);

  for (const [key, entries] of Object.entries(gastosRecientes)) {
    if (entries.length >= minMovimientos) {
      const dates = entries.map(e => e.fecha).sort((a, b) => new Date(a) - new Date(b));
      const amounts = entries.map(e => e.monto);

      // Check similar amounts (within variance from mean)
      const avgAmount = amounts.reduce((s, a) => s + a, 0) / amounts.length;
      const maxDev = amounts.reduce((max, a) => Math.max(max, Math.abs(a - avgAmount) / Math.max(avgAmount, 1)), 0);
      const amountsSimilar = maxDev <= varianzaMaxima;

      // Check evenly spaced intervals (stddev <= configured days)
      let intervals = [];
      for (let i = 1; i < dates.length; i++) {
        intervals.push((new Date(dates[i]) - new Date(dates[i-1])) / (1000 * 60 * 60 * 24));
      }
      const meanInt = intervals.reduce((s, d) => s + d, 0) / intervals.length;
      const variance = intervals.reduce((s, d) => s + Math.pow(d - meanInt, 2), 0) / intervals.length;
      const stddev = Math.sqrt(variance);
      const evenlySpaced = stddev <= stddevDias;

      if (amountsSimilar || evenlySpaced) {
        const [cat] = key.split('-');
        recommendations.push({
          user_id: userId,
          contenido: render(r4.plantilla, { cat, entries }),
          tipo: 'consejo',
          leida: false
        });
      }
    }
  }
}

// Return recommendations as a single item with the full array for batch POST
return [{ json: { recommendations } }];
